  const fetchData = async () => { const sequence=++loadSequence.current;const r = await fetch('/api/bootstrap'); if (r.status === 401) { setError('auth'); return; } if (!r.ok) throw new Error('Could not load your workspace.'); const result=await r.json();if(sequence===loadSequence.current){setData(result);setError('');} };
  useEffect(() => { if (isDemo) return; fetchData().catch(e => setError(e.message)); const id = setInterval(() => fetchData().catch(() => {}), 30000); return () => clearInterval(id); }, []);
  useEffect(() => { const handler = e => { if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); setModal({ type: 'search' }); } }; document.addEventListener('keydown', handler); return () => document.removeEventListener('keydown', handler); }, []);
  const navigate = id => { setPage(id); setMobile(false); setSearch(''); setFilter('all'); };
  const request = async (path, method = 'POST', body) => {
    const response = await fetch(`/api${path}`, { method, headers: { 'Content-Type': 'application/json', 'X-CSRF-Token': data.csrf }, ...(body ? { body: JSON.stringify(body) } : {}) });
    const result = await response.json(); if (!response.ok) throw new Error(result.error || 'Request failed.'); return result;
  };
  const mutate = async (path, method, body, update, message) => {
    setBusy(true);
    try {
      let result;
      if (isDemo) { const next = structuredClone(data);const target=path.match(/^\/servers\/([^/]+)(?:\/hosting(?:\/actions)?)?$/);if(target&&next.workflow_data?.runs.some(run=>run.server_id===target[1]&&['queued','running','waiting'].includes(run.status)))throw new Error('Cancel the active workflow before changing this server or requesting a hosting action.');result = update(next);if(/^\/(servers|schedules|templates|maintenance-windows|incidents|moderation|workflows|workflow-runs|config-templates|config-applications)(\/|$)/.test(path))next.team?.audit.unshift({id:crypto.randomUUID(),actor:next.user.name,action:method+' '+path,created_at:Date.now()});syncDemoProfiles(next); storeDemo(next); setData(next); }
      else { result = await request(path, method, body); await fetchData(); }
      if (message) notify(message); return { ok: true, result };
    } catch (e) { if (!isDemo) await fetchData().catch(() => {}); notify(e.message, true); return { ok: false }; } finally { setBusy(false); }
  };
  const log = (d, title, detail, level = 'success', server_id = null) => d.activity.unshift({ id: crypto.randomUUID(), title, detail, level, server_id, created_at: Date.now() });
  if (!data) return <LoginPage error={error} retry={() => fetchData().catch(e => setError(e.message))} themeControl={themeControl}/>;
  const switchWorkspace=async workspace_id=>{setBusy(true);try{await request('/workspaces/switch','POST',{workspace_id});setModal(null);setPage('overview');await fetchData();}catch(error){notify(error.message,true);}finally{setBusy(false);}};
  const clearInvite=()=>{try{sessionStorage.removeItem('rookrift-pending-invite');}catch{}setInviteToken('');};
