  if(data.access&&data.access.role!=='owner')return <StaffDashboard key={data.workspace.id} data={data} request={request} mutate={mutate} busy={busy} onSwitch={switchWorkspace} themeControl={themeControl} Dialog={Modal} banner={inviteBanner} notice={toast} dismissNotice={()=>setToast(null)} notify={notify}/>;
  const plan = PLANS[data.workspace.plan] || PLANS.scout;
