      if(task.action==='backup'&&!d.hosting_links?.some(link=>link.server_id===server.id&&hostingCapabilities(link.provider).backups))throw new Error('Connect a hosting provider before scheduling backups.');
      task.last_run = Date.now(); task.last_status = servers.find(item=>item.id===server.id)?.in_maintenance ? 'skipped' : server.status === 'offline' ? 'failed' : 'success';
